import{_ as a,o as e,a as i,b as l}from"./app.C41L12d5.js";const o="/ascendc.github.io/assets/250925154552953.D_6gWAN0.png",n="/ascendc.github.io/assets/skip_write_mode.DhHOTf5b.png",s="/ascendc.github.io/assets/skip_write_mode_46.BEe0Thyv.png",c="/ascendc.github.io/assets/250925161748040.BENp11cc.png",r="/ascendc.github.io/assets/SBNGD.PGZwQG6H.png",d="/ascendc.github.io/assets/BNGS1S2.Ch355KwZ.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel"},{"text":"IterateBatch","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateBatch"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateBatch.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateBatch.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787294517000}'),h={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateBatch.md"};function u(p,t,m,A,B,b){return e(),i("div",null,[...t[0]||(t[0]=[l('<div><article class="markdown-body"><h1>IterateBatch</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>单次Matmul计算处理的shape比较小时，由于每次计算均涉及到内部的通信，可能会影响性能，该接口提供批量处理Matmul的功能，调用一次IterateBatch，可以计算出多个singleCoreM * singleCoreN大小的C矩阵。</p><p>在使用该接口前，需要了解一些必备的数据排布格式：</p><ul><li><p><strong>通用数据格式（NORMAL）</strong>：BMNK的数据排布格式；B：Batch，批处理的大小；M、N、K为矩阵乘[M, K]*[K, N]的矩阵维度；其数据排布格式如下：</p><p><img src="'+o+'" alt></p></li><li><p><strong>BSH/SBH</strong>：B：Batch，批处理的大小； S：sequence length，序列长度；H = N * D，其中，N为head的数量，D为head的大小。Layout格式如下图所示：</p><p><img src="'+n+'" alt></p><p><img src="'+s+'" alt></p></li><li><p><strong>BSNGD</strong>：为原始BSH shape做reshape后的shape，S和D为单Batch的矩阵乘的M轴（或N轴）和K轴，一个SD为一个batch的计算数据，Layout格式如下图所示：</p><p><img src="'+c+'" alt></p></li><li><p><strong>SBNGD</strong>：为原始SBH shape做reshape后shape，S和D为矩阵乘的M轴（或N轴）和K轴，一个SD为一个Batch的计算数据，Layout格式如下图所示：</p><p><img src="'+r+'" alt></p></li><li><p><strong>BNGS1S2</strong>：一般为前两种Layout进行矩阵乘的输出，S1S2数据连续存放，一个S1S2为一个Batch的计算数据，Layout格式如下图所示：</p><p><img src="'+d+`" alt></p></li></ul><p>实例化Matmul时，需要通过MatmulType设置输入输出的Layout格式，当前支持4种Layout类型：BSNGD、SBNGD、BNGS1S2、NORMAL（BMNK的数据排布格式使用NORMAL表示）。</p><p>对于BSNGD、SBNGD、BNGS1S2 Layout格式，调用该接口之前需要在host Tiling实现中使用<a href="../Matmul_Tiling/SetALayout.html">SetALayout</a>、<a href="../Matmul_Tiling/SetBLayout.html">SetBLayout</a>、<a href="../Matmul_Tiling/SetCLayout.html">SetCLayout</a>、<a href="../Matmul_Tiling/SetBatchNum.html">SetBatchNum</a>设置A/B/C的Layout轴信息和最大BatchNum数；对于NORMAL Layout格式则需使用<a href="../Matmul_Tiling/SetBatchInfoForNormal.html">SetBatchInfoForNormal</a>设置A/B/C的M/N/K轴信息和A/B矩阵的BatchNum数。</p><p><span id="row_width"></span>使用ND格式输入时，是否开启MatmulConfig中的intrinsicsCheck，取决于单个BMM内A或B矩阵的源矩阵内轴长度。该内轴可理解为源ND数据中一行的连续跨度，即一次ND2NZ搬运所使用的源行宽。不同Layout下的取值规则如下：NORMAL Layout下，按普通矩阵内轴判断；BNGS1S2 Layout下，按源ND矩阵一行的实际跨度判断；BSNGD Layout下，A和B矩阵源矩阵内轴分别为ALayoutInfoN * ALayoutInfoG * ALayoutInfoD、BLayoutInfoN * BLayoutInfoG * BLayoutInfoD；SBNGD Layout下，A和B矩阵源矩阵内轴分别为ALayoutInfoB * ALayoutInfoN * ALayoutInfoG * ALayoutInfoD、BLayoutInfoB * BLayoutInfoN * BLayoutInfoG * BLayoutInfoD。</p><p>单个矩阵乘迭代顺序可通过tiling参数iterateOrder调整。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>mix模式</p><ul><li><p>输出至GM</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;bool sync = true, bool waitIterateBatch = false&gt;
__aicore__ inline void IterateBatch(const GlobalTensor&lt;DstT&gt;&amp; gm, uint32_t batchA, uint32_t batchB, bool enSequentialWrite, const uint32_t matrixStrideA = 0, const uint32_t matrixStrideB = 0, const uint32_t matrixStrideC = 0, const bool enPartialSum = false, const uint8_t enAtomic = 0)
</code></pre></div></li><li><p>输出至Unified Buffer（UB，VECIN）</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;bool sync = true&gt;
__aicore__ inline void IterateBatch(const LocalTensor&lt;DstT&gt;&amp; ubCmatrix, uint32_t batchA, uint32_t batchB, bool enSequentialWrite, const uint32_t matrixStrideA = 0, const uint32_t matrixStrideB = 0, const uint32_t matrixStrideC = 0, const bool enPartialSum = false, const uint8_t enAtomic = 0)
</code></pre></div></li></ul></li><li><p>纯cube模式</p><p>使用前需先调用<a href="SetBatchNum.html">SetBatchNum</a>接口设置batchA和batchB的大小。</p><ul><li><p>输出至GM</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>__aicore__ inline void IterateBatch(const GlobalTensor&lt;DstT&gt;&amp; gm, bool enPartialSum, uint8_t enAtomic, bool enSequentialWrite, const uint32_t matrixStrideA = 0, const uint32_t matrixStrideB = 0, const uint32_t matrixStrideC = 0)
</code></pre></div></li><li><p>输出至UB（VECIN）</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>__aicore__ inline void IterateBatch(const LocalTensor&lt;DstT&gt;&amp; ubCmatrix, bool enPartialSum, uint8_t enAtomic, bool enSequentialWrite, const uint32_t matrixStrideA = 0, const uint32_t matrixStrideB = 0, const uint32_t matrixStrideC = 0)
</code></pre></div></li></ul></li></ul><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>sync</td><td>获取C矩阵过程分为同步和异步两种模式：<br>同步：需要同步等待IterateBatch执行结束。<br>异步：不需要同步等待IterateBatch执行结束。<br><br>通过该参数设置同步或者异步模式：同步模式设置为true；异步模式设置为false。默认为同步模式。异步场景需要配合<a href="WaitIterateBatch.html">WaitIterateBatch</a>接口使用。</td></tr><tr><td>waitIterateBatch</td><td>是否需要通过<a href="WaitIterateBatch.html">WaitIterateBatch</a>接口等待IterateBatch执行结束，仅在异步场景下使用。默认为false。<br><br>true：需要通过WaitIterateBatch接口等待IterateBatch执行结束。<br><br>false：不需要通过WaitIterateBatch接口等待IterateBatch执行结束，开发者自行处理等待IterateBatch执行结束的过程。</td></tr></tbody></table><p><strong>表2</strong> 接口参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>gm</td><td>输出</td><td>C矩阵。类型为<a href="../../../basic_api/data_structures/GlobalTensor/GlobalTensor.html">GlobalTensor</a>。不同型号支持的数据类型请参考<a href="#li12616155731722">支持的数据类型</a>。</td></tr><tr><td>ubCmatrix</td><td>输出</td><td>C矩阵。类型为<a href="../../../basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>。不同型号支持的数据类型请参考<a href="#li12616155731722">支持的数据类型</a>。</td></tr><tr><td>batchA</td><td>输入</td><td>左矩阵的batch数。</td></tr><tr><td>batchB</td><td>输入</td><td>右矩阵的batch数。在batchA/batchB不相同的情况下，默认做broadcast操作。<br><br>多batch计算支持在G轴上做输入broadcast和输出reduce，左矩阵、右矩阵G轴维度必须是整数倍的关系。</td></tr><tr><td>enSequentialWrite</td><td>输入</td><td>输出是否<a href="GetTensorC.html#fig580415103338">连续存放</a>数据，即是否开启连续写模式（连续写，写入[baseM, baseN]；非连续写，写入[singleCoreM, singleCoreN]中对应的位置）。<br>左右矩阵和输出矩阵的存储位置为UB，则enSequentialWrite参数应配置为true；<br>输出矩阵的存储位置为GM，则enSequentialWrite参数应配置为false。</td></tr><tr><td>matrixStrideA</td><td>输入</td><td>A矩阵源操作数相邻nd矩阵起始地址间的偏移，单位是元素，默认值是0。</td></tr><tr><td>matrixStrideB</td><td>输入</td><td>B矩阵源操作数相邻nd矩阵起始地址间的偏移，单位是元素，默认值是0。</td></tr><tr><td>matrixStrideC</td><td>输入</td><td>该参数预留，保持默认值0即可。</td></tr><tr><td>enPartialSum</td><td>输入</td><td>是否将矩阵乘的结果累加于现有的L0C Buffer（CO1）数据，默认值为false。在L0C累加时，只支持A矩阵和B矩阵相乘的输出C矩阵规格为singleM==baseM &amp;&amp;singleN==baseN。</td></tr><tr><td>enAtomic</td><td>输入</td><td>是否开启Atomic操作，默认值为0。<br><br>参数取值：<br><br>0：不开启Atomic操作<br><br>1：开启AtomicAdd累加操作<br><br>2：开启AtomicMax求最大值操作<br><br>3：开启AtomicMin求最小值操作</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>该接口只支持Norm模板，即BatchMatmul只支持Norm模板。</li><li>使用该接口时，A、B矩阵的Layout格式必须相同。</li><li>对于BSNGD、SBNGD、BNGS1S2 Layout格式，输入A、B矩阵按分形对齐后的多Batch数据总和应小于L1 Buffer的大小；对于NORMAL Layout格式没有这种限制，但需通过MatmulConfig配置输入A、B矩阵多Batch数据大小与L1 Buffer的大小关系；</li><li>对于BSNGD、SBNGD、BNGS1S2 Layout格式，称左矩阵、右矩阵的G轴分别为ALayoutInfoG、BLayoutInfoG，则ALayoutInfoG / batchA = BLayoutInfoG / batchB；对于NORMAL Layout格式，batchA、batchB必须满足倍数关系。</li><li>如果接口输出到UB上，输出C矩阵大小BaseM*BaseN应小于分配的UB内存大小。</li><li>如果接口输出到UB上，且单核计算的N方向大小singleCoreN非32字节对齐，C矩阵的CubeFormat仅支持ND_ALIGN格式，输出C矩阵片时，自动将singleCoreN方向上的数据补齐至32字节。</li><li>对于BSNGD、SBNGD Layout格式，输入输出只支持ND格式数据。对于BNGS1S2、NORMAL Layout格式，输入支持ND/NZ格式数据。</li><li>对于BSNGD、SBNGD Layout格式，不支持连续写模式。</li><li>该接口不支持量化模式，即不支持SetQuantScalar、SetQuantVector接口。</li><li>BSNGD场景，不支持一次计算多行SD，需要算子程序中循环计算，即(ALayoutInfoN * ALayoutInfoG) / batchA、(BLayoutInfoN * BLayoutInfoG) / batchB均为整数。</li><li><strong>异步模式</strong>不支持IterateBatch搬运到UB上。</li><li>当开启MixDualMaster（双主模式）场景时，即模板参数<a href="MatmulConfig.html#matmulconfig-params">enableMixDualMaster</a>设置为true，不支持使用该接口。</li></ul><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT上，不支持A、B矩阵内存逻辑位置为TPosition::VECOUT的输入；输出至VECIN的函数原型当前只支持BSNGD Layout格式。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core上，只支持NORMAL Layout格式。</li><li>Atlas 推理系列产品AI Core上，不支持A、B矩阵内存逻辑位置为TPosition::TSCM的输入。</li></ul></div><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT上，A、B矩阵内存逻辑位置为TPosition::TSCM时，只支持NORMAL Layout格式。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core上，Bias不支持复用，Bias的shape大小必须为Batch * N。</li></ul></div><ul><li>使用该接口时，A矩阵、B矩阵不支持int4b_t类型的输入，即BatchMatmul不支持int4b_t类型的矩阵输入。</li></ul><div data-filter="950,A3,910b,310p,x90"><ul><li><p>支持的数据类型<a id="li12616155731722"></a></p><div data-filter="950"><p>Ascend 950PR/Ascend 950DT，支持的数据类型为：half、bfloat16_t、int32_t、float。</p></div><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half、bfloat16_t、int32_t、float。</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half、bfloat16_t、int32_t、float。</p></div><div data-filter="310p"><p>Atlas 推理系列产品AI Core，支持的数据类型为：half、bfloat16_t、int32_t、float。</p></div><div data-filter="x90"><p>Kirin X90，支持的数据类型为：half、int32_t。</p></div></li></ul></div><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p>纯cube模式的函数调用示例请参考<a href="SetBatchNum.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">调用示例</a>。</p></li><li><p>该示例完成aGM、bGM矩阵乘，结果保存到cGm上，其中aGM、bGM、cGM数据的layout格式均为NORMAL，左矩阵每次计算batchA个MK数据，右矩阵每次计算batchB个KN数据。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 定义matmul type
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half, false, LayoutMode::NORMAL&gt; aType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half, true, LayoutMode::NORMAL&gt; bType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float, false, LayoutMode::NORMAL&gt; cType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType;
// 创建Matmul实例
constexpr static MatmulConfig MM_CFG = GetNormalConfig(false, false, false, BatchMode::BATCH_LESS_THAN_L1);
AscendC::Matmul&lt;aType, bType, cType, biasType, MM_CFG&gt; mm1;
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm1);
mm1.Init(&amp;tiling);
mm1.SetTensorA(gm_a, isTransposeAIn);
mm1.SetTensorB(gm_b, isTransposeBIn);
if (tiling.isBias) {
    mm1.SetBias(gm_bias);
}
// 多batch Matmul计算
mm1.IterateBatch(gm_c, batchA, batchB, false);
</code></pre></div></li><li><p>该示例完成aGM、bGM矩阵乘，结果保存到cGm上，其中aGM数据的layout格式为BSNGD，bGM数据的layout格式为BSNGD，cGM的layout格式为BNGS1S2，左矩阵每次计算batchA个SD数据，右矩阵每次计算batchB个SD数据。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 定义matmul type
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half, false, LayoutMode::BSNGD&gt; aType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half, true, LayoutMode::BSNGD&gt; bType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float, false, LayoutMode::BNGS1S2&gt; cType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType;
// 创建Matmul实例
AscendC::Matmul&lt;aType, bType, cType, biasType&gt; mm1;
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm1);
mm1.Init(&amp;tiling);
int batchC = batchA &gt; batchB ? batchA : batchB;
int g_lay = tiling.ALayoutInfoG &gt; tiling.BLayoutInfoG ? tiling.ALayoutInfoG : tiling.BLayoutInfoG;
// 计算需要多Batch计算循环次数
int for_exent = tiling.ALayoutInfoB * tiling.ALayoutInfoN * g_lay / tiling.BatchNum;
for (int i = 0; i &lt; for_exent; ++i) {
    // 计算每次多batch计算A/B矩阵的起始地址
    int batchOffsetA = i * tiling.ALayoutInfoD * batchA;
    int batchOffsetB = i * tiling.BLayoutInfoD * batchB;
    mm1.SetTensorA(gm_a[batchOffsetA], isTransposeAIn);
    mm1.SetTensorB(gm_b[batchOffsetB], isTransposeBIn);
    int idx_c = i * batchC;
    if (tiling.CLayoutInfoG == 1 &amp;&amp; (tiling.BLayoutInfoG != 1 || tiling.ALayoutInfoG != 1)) {
        idx_c = idx_c / (tiling.BLayoutInfoG &gt; tiling.ALayoutInfoG ? tiling.BLayoutInfoG : tiling.ALayoutInfoG);
    }
    if (tiling.isBias) {
        int batchOffsetBias = idx_c * tiling.CLayoutInfoS2;
        mm1.SetBias(gm_bias[batchOffsetBias]);
    }
    int batchOffsetC = idx_c * tiling.CLayoutInfoS2;
    if (C_TYPE::layout == LayoutMode::BNGS1S2) {
        batchOffsetC = idx_c * tiling.CLayoutInfoS2 * tiling.CLayoutInfoS1;
    }
    // 多batch Matmul计算
    mm1.IterateBatch(gm_c[batchOffsetC], batchA, batchB, false);
}
</code></pre></div></li></ul></article></div>`,1)])])}const _=a(h,[["render",u]]);export{g as __pageData,_ as default};
